from h import *

nueva('craterellus-tubaeformis', cient='Craterellus tubaeformis', sin=['Cantharellus tubaeformis'], es=[], eu=['saltsa-perretxiko horilun'], grupo='pliegues', clase='sin_datos', cand=True,
  nomen='Antes se llamaba Cantharellus tubaeformis; los análisis genéticos la pasaron a Craterellus. En inglés: winter chanterelle, yellowfoot, funnel chanterelle.',
  clave='Setita en trompeta de sombrero pardo-grisáceo con pliegues poco marcados, bifurcados y pálidos que bajan por un pie hueco amarillo. Sale tarde, en grupos grandes entre musgo y madera podrida.',
  mirar=[q('sombrero', 'Pardo-grisáceo, en embudo', '1–4 cm. Generalmente plano con el centro hundido, forma de embudo, ceroso y con el borde ondulado. Olor y sabor suaves.'),
         q('himenio', 'Pliegues poco profundos', 'Pliegues (parecen láminas) poco profundos, decurrentes, bifurcados y pálidos.'),
         q('pie', 'Hueco y amarillo', '2–12 cm de alto y 1 cm o menos de ancho; hueco.'),
         q('olor', 'Sabor ahumado y picante en crudo', 'Cuando está cruda tiene un sabor muy característico, ahumado y picante.'),
         q('esporada', 'Esporada naranja-rosa claro', 'Esporas blanquecinas, y huella de color naranja rosado claro.'),
         q('habitat', 'Grupos grandes, entre musgo', 'Suele salir más tarde que otras setas, a veces cerca del Hydnum repandum, y casi siempre en grupos grandes en bosques con mucha madera podrida gruesa, sobre musgo o madera.')],
  conf=[c('cantharellus-cibarius', 'Cantharellus cibarius (rebozuelo)', 'Es más grande, amarillo y en embudo, y de sabor más suave y afrutado.', 'baja'),
        c('cortinarius-orellanus', 'Cortinarius orellanus', 'Las setas pardo-anaranjadas con láminas verdaderas color óxido se confunden con chantarelas: aquí no hay láminas verdaderas sino pliegues.', 'alta'),
        c(None, 'Craterellus lutescens y C. odoratus', 'C. lutescens tiene el himenio arrugado sin láminas y vive solo en sitios muy húmedos. C. odoratus es amarillo vivo con el sombrero y el pie sin separación.', 'baja')],
  hab=['coniferas', 'mixto', 'madera'], habt='Muy común en bosques con mucha madera podrida gruesa, sobre musgo o madera; en América del Norte, sobre todo en turberas de coníferas. Es micorrícica, lo que dificulta cultivarla. Como todas las micorrizas, necesita su árbol.',
  rec=dict(acc='cortar', txt='Corte limpio por la base con navaja. Son setas pequeñas y salen en grupos grandes: coge solo lo que vayas a consumir.'),
  esp='naranja-rosa claro',
  cur=['Aunque es pequeña, Wikipedia la califica como «de primera»: se come con carne, en sopas, pasta y otros platos.',
       'Pasó de Cantharellus a Craterellus gracias a los análisis moleculares.',
       'En el noroeste del Pacífico (Norteamérica) se encuentra de noviembre a enero.'],
  meses=[], mnota=None, wp=['craterellus-tubaeformis'], rioja=False)

nueva('lycoperdon-perlatum', cient='Lycoperdon perlatum', sin=['Lycoperdon gemmatum'], es=['pedo de lobo', 'cuesco de lobo', 'bejín perlado'], eu=['otsoputz', 'astaputz', 'astoputz', 'astaputz perladun'], grupo='bola', clase='sin_datos', cand=True,
  nota='Solo se come joven, con el interior completamente blanco. Hay que evitar confundirlo con Amanitas jóvenes (en huevo), que son venenosas.',
  clave='Bola o pera blanca cubierta de pinchitos cónicos y verrugas que se caen y dejan una red. Comestible solo joven y totalmente blanca por dentro; cuidado con los «huevos» de Amanita.',
  mirar=[q('sombrero', 'Forma de pera o bola', 'De 1,5–6 cm de ancho y 3–9 cm de alto; desde pera con la parte de arriba aplanada hasta casi esférica. Con una base como un pie. Blanquecina, parda con la edad.'),
         q('cutis', 'Pinchos y verrugas que se caen', 'Cubierta de espinas cónicas cortas (blancas, grises o pardas) entre verrugas granulosas. Se quitan fácil y dejan cicatrices en forma de red.'),
         q('carne', 'Interior blanco y firme', 'De joven el interior (gleba) es blanco y firme. Al madurar se vuelve amarillento y al final un polvo verde oliva: ya no se recoge.'),
         q('otro', 'Agujero en lo alto cuando madura', 'El madurar se abre un agujero (ostiolo) arriba y suelta las esporas en nubecitas si la tocas o le caen gotas de lluvia.'),
         q('habitat', 'Bosques, hierba y caminos', 'Saprobia; sola, dispersa o en grupos, a veces en corros de brujas.')],
  conf=[c('amanita-phalloides', 'Amanitas jóvenes (en huevo)', 'Wikipedia advierte de la confusión con Amanitas venenosas inmaduras. Parte la seta por la mitad: debe ser blanca y homogénea por dentro; si ves la silueta de una seta, no es un bejín.', 'alta'),
        c('scleroderma-citrinum', 'Scleroderma citrinum (falso bejín)', 'Tóxico. No tiene un agujero arriba, su carne es mucho más firme y su interior se oscurece muy pronto, mientras que el bejín joven es blanco por dentro.', 'media')],
  hab=['bosque', 'prado', 'cuneta'], habt='Muy común: aparece en gran cantidad de tipos de bosques, en praderas, jardines y claros con hierba, y junto a caminos.',
  rec=dict(acc='cortar', txt='Coge solo ejemplares jóvenes y parte cada uno por la mitad: el interior tiene que ser completamente blanco y homogéneo. Desecha los que están amarillentos o con polvo.'),
  cur=['Se le llama «mollejas del pobre» por la textura y el sabor.',
       'A veces confunde a los jugadores de golf porque, de lejos, parece una pelota.',
       'Las esporas salen con las gotas de lluvia: un estudio con una especie parecida (L. pyriforme) mostró que bastan gotas de 1 mm o más, incluso las que caen de los árboles.',
       'Ya en 1861 Elias Fries la recomendaba seca con sal, pimienta y aceite.',
       'Se vende en mercados de los estados mexicanos de Puebla y Tlaxcala.'],
  meses=[], mnota=None, wp=['lycoperdon-perlatum'], rioja=False)

nueva('laetiporus-sulphureus', cient='Laetiporus sulphureus', sin=['Boletus sulphureus'], es=[], eu=['ardagai hori', 'ardagai horia'], grupo='poliporo', clase='sin_datos', cand=True,
  nota='Wikipedia: comestible joven y cocinado, nunca crudo. En torno al 10 % de las personas tienen reacciones graves (vómitos, fiebre) y otras molestias digestivas.',
  clave='Repisas amarillo azufre a naranja, superpuestas, de aspecto de ante, sobre troncos. Solo bordes jóvenes, nunca crudo: algunas personas tienen reacciones fuertes.',
  mirar=[q('sombrero', 'Repisas superpuestas', 'Sale directo del tronco, primero como un bulto y enseguida como abanicos o estantes, normalmente en pisos que se solapan. Cada estante de 5 a 60 cm de ancho y 4–12 cm de grosor.'),
         q('cutis', 'Amarillo azufre a naranja', 'De amarillo azufre a naranja vivo, con textura como de ante. Los viejos se vuelven pardos o blanquecinos.'),
         q('himenio', 'Poros diminutos amarillos', 'La cara de abajo es amarillo azufre con poros o tubos finos; la esporada es blanca.'),
         q('carne', 'Jugosa de joven, seca de vieja', 'De joven es jugosa, con olor fúngico fuerte y un jugo amarillento transparente. Enseguida se pone seca y quebradiza.'),
         q('habitat', 'Sobre frondosas', 'Sobre frondosas muertas o maduras (roble, cerezo, peral, chopo, sauce, falsa acacia, haya…), a veces en coníferas. En el Mediterráneo, sobre algarrobo y eucalipto.')],
  conf=[c(None, 'Laetiporus persicinus', 'Wikipedia solo dice que se le puede parecer.', 'baja')],
  hab=['frondosas', 'robledal', 'hayedo', 'arbol_vivo', 'madera'], habt='Sobre frondosas muertas o maduras y, de forma ocasional, coníferas; suele salir en grupos. Provoca una pudrición cúbica parda del duramen en las raíces, la base y el tronco, así que parasita árboles vivos.',
  rec=dict(acc='cortar', txt='Wikipedia: solo se comen los ejemplares jóvenes, que sueltan mucho líquido claro o amarillo pálido, y solo los bordes tiernos de los grandes; no se come cruda.'),
  esp='blanca', sind='Molestias digestivas; en torno al 10 % de las personas, reacciones graves con vómitos y fiebre.', lat=None, grav=None,
  cur=['En inglés se llama «chicken of the woods» (pollo del bosque) por el sabor: a algunas personas les sabe a cangrejo o langosta.',
       'Se considera muy apreciada en Alemania y Norteamérica.',
       'Algunas especies de ciervo la consumen.',
       'La describió Pierre Bulliard en 1789 como Boletus sulphureus.'],
  meses=[4, 5, 6, 7, 8, 9, 10, 11], mnota='Europa: de abril a noviembre; sobre todo de agosto a octubre.', wp=['laetiporus-sulphureus'], rioja=False)

nueva('fistulina-hepatica', cient='Fistulina hepatica', sin=[], es=['hongo bistec', 'lengua de buey'], eu=['idi-mihi', 'idi-mina'], grupo='poliporo', clase='sin_datos', cand=True,
  clave='Lengua rojiza y carnosa en roble o castaño que, al cortarla, «sangra» un jugo rojo y parece carne cruda.',
  mirar=[q('sombrero', 'Forma de lengua, rojiza', '7–30 cm de ancho y 2–6 cm de grosor. Parece una lengua grande de superficie áspera; rosa-rojiza de joven y pardo-rojiza con los años.'),
         q('himenio', 'Crema-blanquecino, con poros', 'Cara inferior de color crema-blanquecino, formada por tubos y poros finos.'),
         q('pie', 'Pie corto o ausente', 'Si lo tiene, mide hasta 5 cm.'),
         q('carne', 'Sangra jugo rojo', 'Al cortarla suelta un jugo rojo apagado que mancha, y la carne parece carne cruda. Sabor ácido.'),
         q('esporada', 'Esporada rosa', 'Rosada.'),
         q('habitat', 'En robles y castaños', 'Se ve a menudo en robles y castaño dulce, vivos o muertos, de agosto a finales de otoño.')],
  conf=[c(None, 'Otros poliporos', 'Pseudofistulina radicata, Amylocystis lapponica, Ischnoderma resinosum, Leptoporus mollis y Rhodofomes cajanderi (Wikipedia).', 'baja')],
  hab=['robledal', 'castanar', 'arbol_vivo', 'madera'], habt='Sobre robles y castaños dulces, vivos o muertos. Provoca una pudrición parda. Mancha de pardo rojizo la madera de los robles vivos, y esa madera es apreciada.',
  rec=dict(acc='cortar', txt='Wikipedia: los ejemplares viejos hay que remojarlos toda la noche, porque su jugo puede dar molestias de estómago. No se conserva bien.'),
  esp='rosa',
  cur=['Su jugo rojo y su aspecto de carne cruda le dan nombres como «hongo bistec» o «lengua de buey».',
       'Al infectar un roble vivo lo tiñe de pardo rojizo, y esa madera «de roble pardo» se valora.',
       'La Wikipedia en euskera dice que es muy rica en vitamina C, con más que muchos cítricos.'],
  meses=[7, 8, 9, 10], mnota='Europa: de julio a octubre.', wp=['fistulina-hepatica'], rioja=False)
